// Registers the film as one composition. Length, frame rate and size come from out/timing.json,
// so the editor always matches the render pipeline.
import React from 'react';
import {Composition} from 'remotion';
import {Film} from './Film';
// @ts-ignore: generated by render/prepare.mjs
import timing from '../../out/timing.json';

export const RemotionRoot: React.FC = () => (
  <Composition
    id="DeepMindRSA60s"
    component={Film}
    durationInFrames={Math.round(timing.total * timing.fps)}
    fps={timing.fps}
    width={1080}
    height={1920}
  />
);
